import{_ as s}from"./chunks/start.DZ5W2yLf.js";import{_ as r,C as a,o,c as l,a3 as d,j as i,E as t}from"./chunks/framework.B9qR_F1m.js";const T=JSON.parse('{"title":"Die erste Mission in 5 Minuten","description":"","frontmatter":{},"headers":[],"relativePath":"start/erste-mission.md","filePath":"start/erste-mission.md"}'),g={name:"start/erste-mission.md"},u={class:"tiles"},p={class:"tile",href:"./oberflaeche"},c={class:"tile-icon"},h={class:"tile",href:"../ablaeufe/designer"},m={class:"tile-icon"},b={class:"tile",href:"../gemeinsam/teilen"},f={class:"tile-icon"};function k(S,e,_,M,w,D){const n=a("Icon");return o(),l("div",null,[e[6]||(e[6]=d('<h1 id="die-erste-mission-in-5-minuten" tabindex="-1">Die erste Mission in 5 Minuten <a class="header-anchor" href="#die-erste-mission-in-5-minuten" aria-label="Permalink to &quot;Die erste Mission in 5 Minuten&quot;">​</a></h1><p>Ziel: eine Mission öffnen, für einen F-16-Flight eine Cartridge und eine Lineup Card bauen, und alles zurück in die .miz schreiben. Danach lädt der Jet in DCS deine Steerpoints und im Kneeboard liegt die Karte.</p><p><img src="'+s+'" alt="Startbildschirm von Shardwing" loading="lazy"></p><div class="tip custom-block"><p class="custom-block-title">Erst mal nur schauen?</p><p>Auf dem Startbildschirm öffnet <strong>Beispiel ansehen</strong> die Demo-Mission „Operation Desert Veil“: zwei F-16-Flights über Syrien, fertig geplant mit Cartridges, Lineup Cards, Kneeboards, Timing und IADS. Alle Bilder in diesem Handbuch stammen aus ihr. Ändern und speichern darfst du sie wie jede andere Mission.</p></div><ol class="steps"><li><p><strong>Mission öffnen.</strong> Zieh deine <code>.miz</code> ins Fenster – oder oben links auf <strong>Öffnen</strong> (<kbd>⌘O</kbd> / <kbd>Strg+O</kbd>). Shardwing liest die Mission in ein, zwei Sekunden und springt in den Bereich <strong>Flights</strong>.</p></li><li><p><strong>Flight wählen.</strong> Links stehen alle spielbaren Flights, nach Koalition sortiert. Klick einen F-16-Flight an. Auf der Karte erscheint seine Route, unten die Tabelle mit allen Wegpunkten.</p></li><li><p><strong>Bedrohungen freigeben.</strong> Wechsle zu <strong>Intel</strong>. Alle SAM-Stellungen der Mission sind zuerst <em>verborgen</em> – Shardwing verrät den Piloten nichts, was sie nicht wissen sollen. Klick auf eine Stellung und gib sie frei, oder nimm <strong>Alle aus Mission freigeben</strong>. (<a href="/bereiche/intel">Mehr zu Intel</a>)</p></li><li><p><strong>Cartridge anlegen.</strong> Zurück zu <strong>Flights</strong>, Reiter <strong>DTC</strong>, dann <strong>Neu aus Route</strong>. Shardwing übernimmt Wegpunkte, Funk und die freigegebenen Threats. Deine eigenen CMDS-Programme bleiben dabei unangetastet. (<a href="/bereiche/dtc">Mehr zum DTC</a>)</p></li><li><p><strong>Lineup Card ausfüllen.</strong> Reiter <strong>Lineup Card</strong>: Joker und Bingo eintragen, fertig. Rechts siehst du die Seiten, wie sie im Kneeboard aussehen werden – Lineup Card, Comm Card, Routenkarte. Mit <strong>In .miz einbetten…</strong> landen sie im Kneeboard des Flugzeugtyps. (<a href="/bereiche/lineup-card">Mehr zur Lineup Card</a>)</p></li><li><p><strong>Speichern.</strong> Oben auf <strong>Speichern</strong> (<kbd>⌘S</kbd> / <kbd>Strg+S</kbd>). Die Desktop-App schreibt die .miz an ihren Platz zurück und sichert die alte Version; im Browser bekommst du sie als Download.</p></li><li><p><strong>In DCS fliegen.</strong> Mission im Mission Editor öffnen oder direkt starten. Im Cockpit auf der DTE-Seite die Cartridge laden (oder vorher <strong>AutoLoad</strong> anhaken) – die Steerpoints stehen im DED, das Kneeboard (Taste <kbd>K</kbd>) zeigt deine Seiten. (<a href="/dcs/cockpit">Im Cockpit</a>)</p></li></ol><div class="tip custom-block"><p class="custom-block-title">Nichts kaputtmachen</p><p>Shardwing ändert nur, was du bearbeitest. Was es nicht kennt – Trigger, Skripte, Einheiten, Wetter, Mod-Daten – bleibt genau so, wie der Mission Editor es geschrieben hat. Und mit <kbd>⌘Z</kbd> / <kbd>Strg+Z</kbd> nimmst du jeden Schritt zurück.</p></div><h2 id="wie-geht-es-weiter" tabindex="-1">Wie geht es weiter? <a class="header-anchor" href="#wie-geht-es-weiter" aria-label="Permalink to &quot;Wie geht es weiter?&quot;">​</a></h2>',7)),i("div",u,[i("a",p,[i("span",c,[t(n,{name:"compass"})]),e[0]||(e[0]=i("span",{class:"tile-title"},"Die Oberfläche",-1)),e[1]||(e[1]=i("span",{class:"tile-text"},"Wo was ist: Leiste, Bereiche, Karte, Panel.",-1))]),i("a",h,[i("span",m,[t(n,{name:"pencil-ruler"})]),e[2]||(e[2]=i("span",{class:"tile-title"},"Ablauf für Designer",-1)),e[3]||(e[3]=i("span",{class:"tile-text"},"Von der .miz bis zum fertigen Briefing-Paket.",-1))]),i("a",b,[i("span",f,[t(n,{name:"users"})]),e[4]||(e[4]=i("span",{class:"tile-title"},"Gemeinsam planen",-1)),e[5]||(e[5]=i("span",{class:"tile-text"},"Mission teilen, Piloten tragen sich selbst ein.",-1))])])])}const A=r(g,[["render",k]]);export{T as __pageData,A as default};
